export function debounce(fn: (...args: any[]) => void, waitMs: number) {
    let timer: ReturnType<typeof setTimeout> | null = null;
    return (...args: any[]) => {
        if (timer !== null) {
            return; // already scheduled
        }
        timer = setTimeout(() => fn(args), waitMs);
        timer = null;
    };
}
```

The issues:
1. When timer is not null, it just returns without canceling the previous timer. This is a cancellation problem - it should cancel the pending timeout.
2. Even if we canceled, the function still returns early, but we should allow the last call to proceed. Actually, looking more carefully: the intended behavior is that if a new call comes in while a previous one is pending, the new call should override it and cancel the old one.

But the current code does:
- If timer is not null, it just returns without doing anything. This means the pending timeout still fires, and the new call is effectively ignored.

The correct behavior should be:
- If timer is not null, cancel it (clearTimeout) and then start a new timer.
- The new call should still have its arguments forwarded.

Also, the timeout should be reset each time a new call arrives, with the same waitMs.

